U8.sql:
select
    dateadd(day, value::int, '2024-01-01'::date) as date_day
from table(flatten(input => array_generate_range(0, 366)))

U9.sql:
select
    dateadd(day, seq4(), '2024-01-01') as date_day
from table(generator(rowcount => 10))

U10.sql:
select
    dateadd(day, seq4(), '2024-01-01'::date) as date_day
from table(generator(timelimit => 1))

U16.sql:
select *
from (select customer_id, channel, total from orders)
pivot (sum(total) for channel in (any order by channel))

U17.sql:
select *
from (select customer_id, channel, total from orders)
pivot (sum(total) for channel in (select distinct channel from orders))

U18.sql:
select *
from (select customer_id, channel, total from orders)
pivot (sum(total) for channel in ('web', 'store') default on null (0))

U19.sql:
select order_id, metric, value
from (select order_id, total, discount from orders)
unpivot include nulls (value for metric in (total, discount))

U21.sql:
select customer_id, channel, total_web, total_store
from (select customer_id, channel, total from orders)
pivot (sum(total) for channel in ('web' as total_web, 'store' as total_store))
